fn main() {
    // Cargo reruns a build script that prints no `rerun-if-changed` whenever any file in the
    // package changes. This script writes generated permission files into `permissions/`, so
    // that made every build stale. Watch only the hand-written inputs.
    for path in ["build.rs", "Cargo.toml", "android", "ios"] {
        println!("cargo:rerun-if-changed={path}");
    }
    // `tauri_plugin` also watches `permissions/`, and creates `permissions/autogenerated` when
    // it is missing. Created during the script's run, the directory is newer than the run's
    // start, so Cargo ran the script again and rebuilt this crate and `beryl_app` in the next
    // command. Ignite's tree reset deletes untracked files, so that happened in every build tree
    // after every reset. The directory is tracked (`autogenerated/.gitkeep`, which the plugin
    // does not read as a permission file) so that it always exists.
    // Only Rust calls these native commands.
    tauri_plugin::Builder::new(&[])
        .android_path("android")
        .ios_path("ios")
        .build();
}
